@@ -1,2 +1,3 @@
 {"type":"pattern","classification":"tactical","recorded_at":"2026-08-22T17:10:28.450Z","evidence":{"seeds":"fabro-759d","commit":"802b69be5b96ee07d2af8abf553e0f7ff5205750"},"name":"thin-main-runnable-core","description":"gofib CLI testability: keep main() as a thin flag.Parse + error-exit shim and put all output logic in run(w io.Writer, count int) error, so tests exercise CLI behavior (counts, formats, invalid -n values) via bytes.Buffer instead of os/exec subprocesses. New flags should validate in run and surface errors through main's stderr+exit-1 path.","files":[".mulch/mulch.config.yaml","fib_test.go","main.go"],"id":"mx-d4cf38"}
 {"type":"failure","classification":"tactical","recorded_at":"2026-08-22T18:08:57.202Z","evidence":{"commit":"423d296789e3a8c6f97e29e6f03f4fe41fb56356"},"description":"A previous implementer pass left a compiled 'gofib' binary in the worktree root (gitignored, so the gate stayed green). Hard rule: build smoke checks must not leave binaries behind — use 'go run .' (builds to cache) or build into a temp dir outside the worktree, and remove any stray binary before finishing the pass.","resolution":"Binary removed with 'rm -f gofib'; smoke checks now use 'go run .' which builds into the Go cache and never touches the worktree.","id":"mx-a58327"}
+{"type":"decision","classification":"tactical","recorded_at":"2026-08-22T20:26:58.408Z","evidence":{"commit":"90dc7ead113103615d224d7ef69c7f9fb81af5a8"},"title":"Pretty-mode column widths come from the last line; prose beats inconsistent examples","rationale":"Seed fabro-0879's example block was internally inconsistent (line lengths 26/26/26/28 chars; no width triple reproduces all four lines), while its prose rule (index width = width of largest index, value width = width of largest value, ': ' separator, right-aligned) is self-consistent and yields equal-length lines. Fib grows monotonically, so the largest index is count and the largest value is Fib(count).","id":"mx-8edfdc"}
diff --git a/fib_test.go b/fib_test.go
index e2ecedd..c3c36e1 100644
--- a/fib_test.go
+++ b/fib_test.go
@@ -3,7 +3,9 @@ package main
 import (
 	"bytes"
 	"encoding/json"
+	"fmt"
 	"math/big"
+	"strconv"
 	"strings"
 	"testing"
 )
@@ -34,6 +36,12 @@ func TestFib(t *testing.T) {
 	}
 }

+// outputLines splits run output into lines, dropping the trailing newline
+// so each printed line can be compared exactly.
+func outputLines(s string) []string {
+	return strings.Split(strings.TrimSuffix(s, "\n"), "\n")
+}
+
 func TestRun(t *testing.T) {
 	tests := []struct {
 		name      string
@@ -52,10 +60,10 @@ func TestRun(t *testing.T) {
 	for _, tt := range tests {
 		t.Run(tt.name, func(t *testing.T) {
 			var buf bytes.Buffer
-			if err := run(&buf, tt.n, false); err != nil {
+			if err := run(&buf, tt.n, false, false); err != nil {
 				t.Fatalf("run(%d) returned error: %v", tt.n, err)
 			}
-			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
+			lines := outputLines(buf.String())
 			if len(lines) != tt.wantLines {
 				t.Fatalf("run(%d) printed %d lines, want %d", tt.n, len(lines), tt.wantLines)
 			}
@@ -93,10 +101,10 @@ func TestRunJSON(t *testing.T) {
 	for _, tt := range tests {
 		t.Run(tt.name, func(t *testing.T) {
 			var buf bytes.Buffer
-			if err := run(&buf, tt.n, true); err != nil {
+			if err := run(&buf, tt.n, true, false); err != nil {
 				t.Fatalf("run(%d, json) returned error: %v", tt.n, err)
 			}
-			lines := strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
+			lines := outputLines(buf.String())
 			if len(lines) != tt.wantLines {
 				t.Fatalf("run(%d, json) printed %d lines, want %d", tt.n, len(lines), tt.wantLines)
 			}
@@ -120,14 +128,81 @@ func TestRunJSON(t *testing.T) {
 	}
 }

+// wantPrettyLine returns the expected -pretty text line for index i when
+// count numbers are printed: index and value are right-aligned in columns
+// as wide as the largest index (count) and the largest value (Fib(count)),
+// separated by ": ". Nothing is hardcoded — widths and values are derived
+// from the same Fib the code under test uses.
+func wantPrettyLine(i, count int) string {
+	return fmt.Sprintf("%*d: %*s",
+		len(strconv.Itoa(count)), i,
+		len(Fib(count).String()), Fib(i).String())
+}
+
+func TestRunPretty(t *testing.T) {
